// Reading a research repo's note/note.md table of contents (written by the
// life repo's scripts/note_toc.py) and choosing pictures under a number's
// data folder, for the notes pane. Pure functions: the tests feed them text.

export type TocRow = { id: string; date: string; title: string; conclusion: string; state: string }

const cellsOf = (row: string) => row.trim().replace(/^\|/, '').replace(/\|$/, '').split(/(?<!\\)\|/).map(c => c.trim().replace(/\\\|/g, '|'))

// The rows of the table between <!-- TOC:START --> and <!-- TOC:END -->.
export function tocRows(md: string): TocRow[] {
  const start = md.indexOf('<!-- TOC:START -->')
  const end = md.indexOf('<!-- TOC:END -->')
  if (start < 0 || end < start) return []
  const out: TocRow[] = []
  for (const line of md.slice(start, end).split('\n')) {
    if (!/^\|\s*KM_[A-Z]\d{4}\s*\|/.test(line)) continue
    const c = cellsOf(line)
    if (c.length < 5) continue
    out.push({ id: c[0], date: c[1], title: c[2], conclusion: c[3], state: c[4] })
  }
  return out
}

// A hub's frontmatter value, the inline comment after "  #" dropped.
export function frontValue(md: string, key: string): string | undefined {
  const fm = md.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? ''
  const line = fm.split('\n').find(l => l.startsWith(`${key}:`))
  if (!line) return undefined
  return line.slice(key.length + 1).replace(/\s+#.*$/, '').trim() || undefined
}

// `find` output → picture paths relative to the number's folder, sorted, at most `max`.
export function pngList(findOut: string, base: string, max = 200): string[] {
  const root = base.replace(/\/+$/, '') + '/'
  return findOut
    .split('\n')
    .map(l => l.trim())
    .filter(l => l.toLowerCase().endsWith('.png') && l.startsWith(root))
    .map(l => l.slice(root.length))
    .sort((a, b) => a.localeCompare(b))
    .slice(0, max)
}

// Terminal rows for a picture `columns` wide: a cell is about twice as tall as wide.
export function imageRows(width: number, height: number, columns: number, maxRows = 40): number {
  if (!width || !height) return Math.min(maxRows, Math.round(columns / 2))
  return Math.max(4, Math.min(maxRows, Math.round((columns * height) / width / 2)))
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// Standard padded base64: what Image's `png` must be.
export function base64(u8: Uint8Array): string {
  let out = ''
  for (let i = 0; i < u8.length; i += 3) {
    const a = u8[i], b = i + 1 < u8.length ? u8[i + 1] : 0, c = i + 2 < u8.length ? u8[i + 2] : 0
    const n = (a << 16) | (b << 8) | c
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63]
    out += i + 1 < u8.length ? B64[(n >> 6) & 63] : '='
    out += i + 2 < u8.length ? B64[n & 63] : '='
  }
  return out
}

// What $.fs.read(path, { as: 'bytes' }) gave, as base64: a session hands
// { base64 }, a test hands bytes (or an object of them).
export function bytesToBase64(r: any): string {
  if (typeof r?.base64 === 'string') return r.base64
  const raw = r?.bytes ?? r
  const u8 = raw instanceof Uint8Array ? raw : Array.isArray(raw) ? Uint8Array.from(raw) : raw && typeof raw === 'object' ? Uint8Array.from(Object.values(raw) as number[]) : new Uint8Array(0)
  return base64(u8)
}

export const isBase64 = (s: string) => s.length > 0 && s.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(s)

// One number's entry in note.md: the lines under its "## <id> — …" heading,
// up to the next "## " heading. `awk` hands over just that span (heading
// included); the whole note works too. No such heading: nothing.
export function entryLines(md: string, id: string): string[] {
  const lines = md.split('\n')
  const at = lines.findIndex(l => l.startsWith(`## ${id} — `))
  if (at < 0) return []
  const out: string[] = []
  for (let i = at + 1; i < lines.length; i++) {
    if (lines[i].startsWith('## ')) break
    out.push(lines[i])
  }
  while (out.length && !out[out.length - 1].trim()) out.pop()
  while (out.length && !out[0].trim()) out.shift()
  return out
}

files.hooks/trend.ts:
// Reading the daily search-trend digest (ideas/daily/md/YYYY-MM-DD-trend.md):
// tables of papers and news, each row a linked original title, its Japanese
// rendering and an interest rating in stars. Pure functions: the tests feed
// them text.

export type TrendItem = {
  source: string // the "### " heading the table sits under
  short: string // a few letters for the one-line view
  title: string
  url: string
  ja: string
  stars: number
  category: string
  order: number // position in the file, for stable sorting
}

export type Trend = { date: string; items: TrendItem[] }

const SHORT: [RegExp, string][] = [
  [/pubmed/i, 'PM'],
  [/biorxiv|europe\s*pmc/i, 'bR'],
  [/nature/i, 'Nat'],
  [/science|aaas/i, 'Sci'],
  [/ナゾロジー/, 'ナゾ'],
]

export function shortSource(source: string): string {
  return SHORT.find(([r]) => r.test(source))?.[1] ?? source.slice(0, 4)
}

const cellsOf = (row: string) =>
  row.trim().replace(/^\|/, '').replace(/\|$/, '').split(/(?<!\\)\|/).map(c => c.trim().replace(/\\\|/g, '|'))

export function parseTrend(md: string): Trend {
  const date = md.match(/^# .*?(\d{4}-\d{2}-\d{2})/m)?.[1] ?? ''
  const items: TrendItem[] = []
  let source = ''
  for (const line of md.split('\n')) {
    const h = line.match(/^###\s+(.+)$/)
    if (h) {
      source = h[1].trim()
      continue
    }
    if (!source || !line.trim().startsWith('|') || /^\|\s*-/.test(line.trim())) continue
    const c = cellsOf(line)
    const link = c[0]?.match(/^\[(.+)\]\((\S+)\)$/)
    if (!link) continue // the header row and anything else without a linked title
    items.push({
      source,
      short: shortSource(source),
      title: link[1],
      url: link[2],
      ja: c[1] ?? '',
      stars: (c[2]?.match(/★/g) ?? []).length,
      category: c[3] ?? '',
      order: items.length,
    })
  }
  return { date, items }
}

// Highest rated first; equal ratings keep the file's order.
export function topItems(items: readonly TrendItem[], n: number): TrendItem[] {
  return [...items].sort((a, b) => b.stars - a.stars || a.order - b.order).slice(0, n)
}

export function starText(n: number): string {
  return '★'.repeat(n) + '☆'.repeat(Math.max(0, 5 - n))
}

// The newest "YYYY-MM-DD-trend.md" among file names.
export function latestTrendFile(names: readonly string[]): string | undefined {
  return names.filter(n => /^\d{4}-\d{2}-\d{2}-trend\.md$/.test(n)).sort().pop()
}

files.hooks/alert.ts:
// The alert pane's pure parts: the Gmail feed's items, how a row reads, and the
// commands a selection turns into. No engine calls, so tests can feed them.
//
// What reaches the model: nothing, until the person presses 詳しく and sends
// the draft it puts in the prompt. A message in a sensitive class (人事・成績・
// 査読 …, decided on the machine in ~/.config/life/alert.json) never gets 詳しく:
// it can be marked Done or put on the calendar, both run here without the model.

export type MailItem = {
  id: string
  thread_id?: string
  from: string
  from_name: string
  subject: string
  date: string
  labels: string[]
  unread: boolean
  bulk: boolean
  sensitive?: string
}

export type MailFeed = { fetched_at: string; items: MailItem[]; error?: string; fetched_new?: number }

export const DONE_LABEL = '9. Done/Triage'

export function parseFeed(stdout: string): MailFeed {
  try {
    const d = JSON.parse(stdout)
    return { fetched_at: String(d.fetched_at ?? ''), items: Array.isArray(d.items) ? d.items : [], error: d.error, fetched_new: d.fetched_new }
  } catch {
    return { fetched_at: '', items: [], error: '取得の結果を読めなかった' }
  }
}

// Ids in `items` not in `seen`: what came since the last look.
export function newIds(seen: ReadonlySet<string> | undefined, items: readonly MailItem[]): string[] {
  if (!seen) return []
  return items.filter(x => !seen.has(x.id)).map(x => x.id)
}

// "10/08 14:32" in the machine's zone.
export function shortDate(iso: string): string {
  const t = Date.parse(iso)
  if (Number.isNaN(t)) return '     '
  const d = new Date(t)
  const two = (n: number) => String(n).padStart(2, '0')
  return `${d.getMonth() + 1}/${two(d.getDate())} ${two(d.getHours())}:${two(d.getMinutes())}`
}

// Personal mail first, newest first; bulk mail (a list-unsubscribe header) after.
export function splitMail(items: readonly MailItem[], done: ReadonlySet<string>): { personal: MailItem[]; bulk: MailItem[] } {
  const live = items.filter(x => !done.has(x.id)).sort((a, b) => Date.parse(b.date) - Date.parse(a.date))
  return { personal: live.filter(x => !x.bulk), bulk: live.filter(x => x.bulk) }
}

// A row's text; the ☐ / ☑ that selects it is a button of its own before it
// (pressing the row opens the mail).
export function mailLine(item: MailItem): string {
  const dot = item.unread ? '●' : ' '
  const tag = item.sensitive ? `［${item.sensitive}］` : ''
  return `${dot} ${shortDate(item.date)}  ${item.from_name}  ${tag}${item.subject}`
}

// One mail with its body, from `alert_feed.py --body` (the pane's own call; the
// model is kept from it by ops-rules). Shown on the terminal, never stored.
export type MailBody = { id: string; from?: string; date?: string; subject?: string; sensitive?: string | null; body?: string; error?: string }

export function bodyArgv(python: string, repo: string, id: string): string[] {
  return [python, `${repo}/scripts/gmail/alert_feed.py`, '--body', id]
}

export function parseBody(stdout: string, id: string): MailBody {
  try {
    const d = JSON.parse(stdout)
    return { id, ...d }
  } catch {
    return { id, error: '本文を読めなかった' }
  }
}

export function doneArgv(python: string, repo: string, ids: readonly string[]): string[] {
  return [python, `${repo}/scripts/gmail_label.py`, ...ids.flatMap(id => ['--message-id', id]), '--add-label', DONE_LABEL]
}

// "2026-10-15 17:00" or "2026-10-15" (then 09:00); a 30-minute block that
// ends at the deadline's time would hide it, so the block starts there.
export function parseWhen(text: string): { start: string; end: string } | { error: string } {
  const m = text.trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2}))?$/)
  if (!m) return { error: '日時は 2026-10-15 17:00 か 2026-10-15 の形で' }
  const [y, mo, d, h, mi] = [m[1], m[2], m[3], m[4] ?? '9', m[5] ?? '00'].map(Number)
  const start = new Date(y, mo - 1, d, h, mi)
  if (start.getMonth() !== mo - 1 || start.getDate() !== d || h > 23 || mi > 59) return { error: 'その日時はありません' }
  const end = new Date(start.getTime() + 30 * 60000)
  const iso = (t: Date) => `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, '0')}-${String(t.getDate()).padStart(2, '0')}T${String(t.getHours()).padStart(2, '0')}:${String(t.getMinutes()).padStart(2, '0')}:00`
  return { start: iso(start), end: iso(end) }
}

export function calendarArgv(python: string, repo: string, title: string, when: { start: string; end: string }): string[] {
  return [python, `${repo}/scripts/google_calendar_create.py`, '--title', title, '--start', when.start, '--end', when.end, '--execute']
}

// A sensitive message's default title says only its class, never its subject
// (a subject can carry the matter itself).
export function calendarTitle(item: MailItem): string {
  return item.sensitive ? `［${item.sensitive}］締切` : `〆 ${item.subject}`
}

// The draft 詳しく puts in the prompt: the ids to read, and what to do. Only
// the person's send hands it to the model; sensitive mail is refused here too.
export function detailPrompt(items: readonly MailItem[], ask: string): string | undefined {
  if (items.length === 0 || items.some(x => x.sensitive)) return undefined
  const lines = items.map(x => `- id ${x.id} — ${shortDate(x.date)} ${x.from_name}「${x.subject}」`)
  return [
    'Gmail の次のメールを読んで、頼んだことをしてください。本文は life repo で `python scripts/gmail/alert_feed.py --show <id>` で 1 通ずつ取る（読むだけ。返信・削除はしない）。',
    ...lines,
    '',
    `頼むこと: ${ask.trim() || '要点と、私がすべきことを短く'}`,
  ].join('\n')
}

